#!/usr/bin/env bash
# Kernel-checked proofs, over the Lean model formal/Bootstrap/X86Min.lean, that
# the two seed loaders reproduce themselves and each other:
#
#   seedA_self   exec seed-a on seed-a.hex  = exit 0, output seed-a
#   seedA_cross  exec seed-a on seed-b.hex  = exit 0, output seed-b
#   seedB_self   exec seed-b on seed-b.oct  = exit 0, output seed-b
#   seedB_cross  exec seed-b on seed-a.oct  = exit 0, output seed-a
#
# Each proof is generated by formal/Bootstrap/GenProof.lean as checkpoint
# lemmas (`decide +kernel`, chunks of $CHUNK steps) and checked by `lean`;
# nothing the generator prints is trusted. The four checks run in parallel.
# Cost, measured 2026-11-15: about 13 s and 2.6 GB per 1000-step chunk.
#
#   bootstrap/model/seed_proofs.sh [outdir]
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
lean="${LEAN_BIN:+$LEAN_BIN/}lean"
chunk="${CHUNK:-1000}"
work="${1:-$(mktemp -d)}"
mkdir -p "$work"

"$root/bootstrap/model/build_model.sh" "$work/olean"
cd "$root/formal"
export LEAN_PATH="$work/olean"

proofs=("seedA_self seedA seedAHex seedA" "seedA_cross seedA seedBHex seedB"
        "seedB_self seedB seedBOct seedB" "seedB_cross seedB seedAOct seedA")
for p in "${proofs[@]}"; do
  set -- $p
  "$lean" --run Bootstrap/GenProof.lean "$1" "$2" "$3" "$4" "$chunk" > "$work/$1.lean"
done

pids=()
for p in "${proofs[@]}"; do
  set -- $p
  ( start=$(date +%s)
    if "$lean" "$work/$1.lean" > "$work/$1.log" 2>&1; then
      echo "PROOF_OK $1 $(( $(date +%s) - start ))s"
    else
      echo "PROOF_FAIL $1"; head -c 2000 "$work/$1.log"; exit 1
    fi ) &
  pids+=($!)
done
fail=0
for pid in "${pids[@]}"; do wait "$pid" || fail=1; done

# The checked theorems must state what they are named for.
for p in "${proofs[@]}"; do
  set -- $p
  grep -qx "theorem X86Min.$1 : exec [0-9]* $2 $3 = Outcome.exit 0 $4 := by" "$work/$1.lean" \
    || { echo "statement of $1 is not exec $2 $3 = exit 0 $4"; fail=1; }
done
[ "$fail" = 0 ] && echo "SEED_PROOFS_OK" || { echo "SEED_PROOFS_FAIL"; exit 1; }
